<?php
namespace App\Entity;use Doctrine\DBAL\Types\Types;use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity]class SupplierInvoice{#[ORM\Id,ORM\GeneratedValue,ORM\Column]private ?int $id=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?Supplier $supplier=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?Stations $station=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:true)]private ?FuelDelivery $delivery=null;#[ORM\Column(length:60)]private string $invoiceNumber='';#[ORM\Column(type:Types::DATE_IMMUTABLE)]private ?\DateTimeImmutable $invoiceDate=null;#[ORM\Column(type:Types::DATE_IMMUTABLE,nullable:true)]private ?\DateTimeImmutable $dueDate=null;#[ORM\Column(type:Types::DECIMAL,precision:15,scale:2)]private string $totalAmount='0';#[ORM\Column(length:30)]private string $invoiceType='FUEL';#[ORM\Column(length:255,nullable:true)]private ?string $description=null;#[ORM\Column(options:['default'=>true])]private bool $isActive=true;#[ORM\Column]private ?\DateTimeImmutable $createdAt=null;public function getId():?int{return $this->id;}public function getSupplier():?Supplier{return $this->supplier;}public function setSupplier(Supplier $v):static{$this->supplier=$v;return $this;}public function getStation():?Stations{return $this->station;}public function setStation(Stations $v):static{$this->station=$v;return $this;}public function getDelivery():?FuelDelivery{return $this->delivery;}public function setDelivery(?FuelDelivery $v):static{$this->delivery=$v;return $this;}public function getInvoiceNumber():string{return $this->invoiceNumber;}public function setInvoiceNumber(string $v):static{$this->invoiceNumber=$v;return $this;}public function getInvoiceDate():?\DateTimeImmutable{return $this->invoiceDate;}public function setInvoiceDate(\DateTimeImmutable $v):static{$this->invoiceDate=$v;return $this;}public function getDueDate():?\DateTimeImmutable{return $this->dueDate;}public function setDueDate(?\DateTimeImmutable $v):static{$this->dueDate=$v;return $this;}public function getTotalAmount():string{return $this->totalAmount;}public function setTotal